/// Message `STS_Msg`.
final class STS_Msg implements BitisMessage {
  /// Creates a [STS_Msg]; omitted attributes get their default values.
  const STS_Msg({this.deviceId = 0, this.msgs = const []});

  /// Lower bound of the encoded size in bits (`min_bits`, bitis
  /// docs/WIRE_FORMAT.md section 4).
  static const int bitisMinBits = 28;

  /// Upper bound of the encoded size in bits (`max_bits`, bitis
  /// docs/WIRE_FORMAT.md section 4); `null` if unbounded (or above 2^53 - 1).
  static const int? bitisMaxBits = null;

  /// Reads a [STS_Msg] from [r].
  static STS_Msg bitisRead(BitReader r) {
    return STS_Msg(
      deviceId: r.readUint(27),
      msgs: r.readDynArray(3, 1, STS_MsgWrapper.bitisRead),
    );
  }

  /// Decodes a [STS_Msg] from the start of [data] (trailing bytes are
  /// ignored). Throws [BitisDecodeException] on invalid input.
  static STS_Msg fromBytes(List<int> data) =>
      bitisDecode(data, bitisRead).value;

  /// Like [fromBytes], but [data] must not contain trailing bytes.
  static STS_Msg fromBytesExact(List<int> data) =>
      bitisDecodeExact(data, bitisRead);

  /// Parses the JSON representation (see [toJson]).
  factory STS_Msg.fromJson(Map<String, dynamic> json) {
    return STS_Msg(
      deviceId: BitisJson.intFromJson(json['device_id']),
      msgs: BitisJson.listFromJsonWith(
        json['msgs'],
        (v) => STS_MsgWrapper.fromJson(BitisJson.objectFromJson(v)),
      ),
    );
  }

  /// `uint_27 device_id`
  final int deviceId;

  /// `repeated_dyn_3 STS_MsgWrapper msgs`
  final List<STS_MsgWrapper> msgs;

  @override
  void bitisWrite(BitWriter w) {
    w.writeUint(deviceId, 27);
    w.writeDynArray(msgs, 3, (w, v) => v.bitisWrite(w));
  }

  /// Encodes this message.
  Uint8List toBytes() => bitisEncode(this);

  /// JSON representation; the keys are the attribute names of the schema.
  Map<String, Object?> toJson() => {
    'device_id': deviceId,
    'msgs': BitisJson.listToJson(msgs, (v) => v.toJson()),
  };

  /// Copy with the given attributes replaced. Optional attributes are cleared
  /// by passing `null`.
  STS_Msg copyWith({int? deviceId, List<STS_MsgWrapper>? msgs}) {
    return STS_Msg(
      deviceId: deviceId ?? this.deviceId,
      msgs: msgs ?? this.msgs,
    );
  }

  @override
  bool operator ==(Object other) =>
      other is STS_Msg &&
      deviceId == other.deviceId &&
      BitisEq.listEquals(msgs, other.msgs);

  @override
  int get hashCode => Object.hashAll([deviceId, BitisEq.listHash(msgs)]);

  @override
  String toString() => 'STS_Msg(deviceId: $deviceId, msgs: $msgs)';
}
